var i=`0529-kuku-sabzi`;var o=`world-0529`;var t=`IR`;var r=`western-asia`;var a=4;var s=38;var u={en:`Kuku Sabzi`,ua:`Куку сабзі`};var l={en:`A traditional dish from Iran, centered on parsley, cilantro, dill, green onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: петрушка, кінза, кріп, зелена цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`parsley`,180,`g`],[`cilantro`,80,`g`],[`dill`,100,`g`],[`green-onion`,120,`g`]]},{en:`Herbs should dominate the eggs by volume; gently mix the thick green batter without bruising the greens.`,ua:`Зелені має бути більше, ніж яєць за об’ємом; обережно перемішайте густу зелену масу.`,t:[`mixing`],m:8,i:[[`chicken-egg`,5,`pcs`],[`all-purpose-flour`,35,`g`],[`walnut`,55,`g`],[`ground-turmeric`,3,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`sunflower-oil`,65,`ml`]]}];var d={slug:i,id:o,country:`IR`,region:r,servings:4,minutes:38,title:u,text:l,steps:g};export{t as country,d as default,o as id,s as minutes,r as region,a as servings,i as slug,g as steps,l as text,u as title};